"""Visual layout shared by the three localised game catalogues."""
from html import escape as E

TEXT={
'pt':dict(title='Um novo jogo.<span>Mais descobertas.</span>',intro='Uma coleção de descobertas, desafios e brincadeiras. Escolha um jogo, veja-o em ação e encontre uma nova forma de brincar em conjunto.',eyebrow='58 jogos · Um mundo de descobertas',browse='Encontrar um jogo',collection='A coleção',choose='Por onde vamos brincar hoje?',results='jogos para descobrir',all='Todos',sound='Vídeo com som',demo='Veja como se joga',first='O desafio',next='Da app para a brincadeira',idea='Uma ideia para experimentar',care='Ao ritmo de cada criança',support='Brincar também é comunicar.',supportIntro='Os jogos podem criar momentos de partilha. Quando existem dúvidas sobre a fala ou o desenvolvimento, o acompanhamento profissional continua a ser essencial.',read='Ler o artigo',discover='Continuar a descobrir',android='Para telemóveis e tablets Android',languages='Português · Inglês · Espanhol',footer='Mais formas de brincar. Mais oportunidades de comunicar.',ready='Vamos descobrir o próximo jogo?',readyText='Leve os jogos, as palavras e as descobertas para o dia a dia da criança.',explore='Explorar a coleção',on='Na app',how='É assim que se joga',family='Para partilhar',light='Pequenos momentos, ao seu ritmo.'),
'en':dict(title='A new game.<span>More to discover.</span>',intro='A collection of discoveries, challenges and play. Choose a game, watch it in action and find a new way to play together.',eyebrow='58 games · A world to discover',browse='Find a game',collection='The collection',choose='Where shall we play today?',results='games to discover',all='All',sound='Video with sound',demo='See how it works',first='The challenge',next='From the app to everyday play',idea='An idea to try together',care='At each child’s pace',support='Play is a way to connect.',supportIntro='Games can create moments to share. When there are questions about speech or development, professional support remains essential.',read='Read the article',discover='Keep discovering',android='For Android phones and tablets',languages='Portuguese · English · Spanish',footer='More ways to play. More opportunities to communicate.',ready='Ready to discover the next game?',readyText='Bring games, words and discoveries into the child’s everyday life.',explore='Explore the collection',on='In the app',how='Here’s how to play',family='To share together',light='Little moments, at their own pace.'),
'es':dict(title='Un nuevo juego.<span>Más por descubrir.</span>',intro='Una colección de descubrimientos, retos y juegos. Elige uno, míralo en acción y encuentra una nueva forma de jugar juntos.',eyebrow='58 juegos · Un mundo por descubrir',browse='Encontrar un juego',collection='La colección',choose='¿A qué vamos a jugar hoy?',results='juegos por descubrir',all='Todos',sound='Vídeo con sonido',demo='Mira cómo se juega',first='El reto',next='De la app al juego cotidiano',idea='Una idea para probar juntos',care='Al ritmo de cada niño',support='Jugar también es conectar.',supportIntro='Los juegos pueden crear momentos compartidos. Cuando hay dudas sobre el habla o el desarrollo, el acompañamiento profesional sigue siendo esencial.',read='Leer el artículo',discover='Seguir descubriendo',android='Para móviles y tabletas Android',languages='Portugués · Inglés · Español',footer='Más formas de jugar. Más oportunidades de comunicarse.',ready='¿Descubrimos el próximo juego?',readyText='Lleva los juegos, las palabras y los descubrimientos al día a día del niño.',explore='Explorar la colección',on='En la app',how='Así se juega',family='Para compartir',light='Pequeños momentos, a su ritmo.')}
ORDER=['logic','memory','speed','aim','language','creative']
def icon(id):return '/assets/games/icons/'+id+'.webp'
def arrow():return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>'
def play():return '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m9 5 11 7-11 7z"/></svg>'
def store(lang,i):
    return f'<a class="game-store" href="https://play.google.com/store/apps/details?id=pt.falaplus.app&amp;hl={lang}" aria-label="{E(i["download"])}"><svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="m3 2 12 10L3 22zm2-1 14 8-3 2zm11 12 3 2-14 8zm1-1 3-2 3 2-3 2z"/></svg><span>{E(i['download'])}<strong>Google Play</strong></span>{arrow()}</a>'
def card(lang,g,i,route,types):
    d=g['locales'][lang];t=TEXT[lang];n=ORDER.index(g['type'])
    return f'''<article class="game-card tone-{g['type']}" data-game-card data-type="{g['type']}" data-search="{E((d['name']+' '+d['tutorial']).lower(),quote=True)}"><a href="{route(lang,g)}"><div class="game-card-art"><img src="{icon(g['id'])}" alt="" width="256" height="256" loading="lazy"><span class="game-card-play">{play()}</span></div><div class="game-card-copy"><span class="game-category">{E(types[n])}</span><h3>{E(d['name'])}</h3><p>{E(d['hook'])}</p><span class="game-card-link">{E(i['watch'])}{arrow()}</span></div></a></article>'''
def support(lang,i,compact=False):
    t=TEXT[lang]
    if compact:
        links=''.join(f'<a href="{i["articles"]+slug}/">{E(topic)} {arrow()}</a>' for topic,slug in zip(i['topics'],i['slugs']))
        hub={'pt':'/explorar/','en':'/en/explore/','es':'/es/explorar/'}[lang]
        return f'<section class="game-support game-support-compact"><div class="support-heading"><p class="game-kicker">{E(t["care"])}</p><h2>{E(t["support"])}</h2><p>{E(t["supportIntro"])}</p></div><p class="game-notice">{E(i["note"])}</p><div class="reading-links">{links}</div><a class="game-back-link" href="{hub}">{E(i["related"])} {arrow()}</a></section>'
    cards=''.join(f'<article><span class="support-index">0{n+1}</span><h3>{E(h)}</h3><p>{E(p)}</p><a href="{i["articles"]+i["slugs"][n]}/">{E(t["read"])} {arrow()}</a></article>' for n,(h,p) in enumerate(i['clinical']))
    # Clinical paragraphs group delay, apraxia and autism; AAC has its own related link.
    links=''.join(f'<a href="{i["articles"]+slug}/">{E(topic)} {arrow()}</a>' for topic,slug in zip(i['topics'],i['slugs']))
    return f'''<section class="game-support"><div class="support-heading"><p class="game-kicker">{E(t['care'])}</p><h2>{E(t['support'])}</h2><p>{E(t['supportIntro'])}</p></div><div class="support-grid">{cards}</div><div class="game-notice">{E(i['note'])}</div><details class="game-reading"><summary>{E(i['related'])}</summary><div class="reading-links">{links}</div></details><details class="game-reading"><summary>{E(i['sources'])}</summary><div class="reading-links"><a href="https://www.asha.org/practice-portal/clinical-topics/late-language-emergence/">ASHA · Late Language Emergence {arrow()}</a><a href="https://www.asha.org/Practice-Portal/Clinical-Topics/Childhood-Apraxia-of-Speech/">ASHA · Childhood Apraxia of Speech {arrow()}</a><a href="https://www.asha.org/practice-portal/clinical-topics/autism/">ASHA · Autism {arrow()}</a></div></details></section>'''
def cta(lang,i):
    t=TEXT[lang]
    return f'<section class="game-bottom-cta"><div><p class="game-kicker">{E(i["brand"])}</p><h2>{E(t["ready"])}</h2><p>{E(t["readyText"])}</p></div>{store(lang,i)}</section>'
def catalog(lang,i,games,route,types):
    t=TEXT[lang]
    featured=[next(g for g in games if g['id']==id) for id in ['tangram','bubble_pop','memory_match','tap_to_paint']]
    collage=''.join(f'<a class="hero-game hero-game-{n}" href="{route(lang,g)}"><img src="{icon(g["id"])}" alt="{E(g["locales"][lang]["name"])}" width="256" height="256"><span>{E(g["locales"][lang]["name"])}</span></a>' for n,g in enumerate(featured))
    filters=f'<button type="button" data-filter="all" aria-pressed="true">{E(t["all"])}</button>'+''.join(f'<button type="button" data-filter="{typ}" aria-pressed="false">{E(label)}</button>' for typ,label in zip(ORDER,types))
    return f'''<section class="games-intro"><div class="games-intro-copy"><p class="game-kicker"><span></span>{E(t['eyebrow'])}</p><h1>{t['title']}</h1><p class="game-lead">{E(t['intro'])}</p><a class="game-primary" href="#colecao">{E(t['browse'])}{arrow()}</a><p class="hero-footnote">Android <span>·</span> PT · EN · ES</p></div><div class="games-collage">{collage}<span class="collage-note">{E(t['light'])}</span></div></section><section class="game-collection" id="colecao"><div class="collection-head"><div><p class="game-kicker">{E(t['collection'])}</p><h2>{E(t['choose'])}</h2></div><div class="games-search" hidden><label class="sr-only" for="game-search">{E(i['search'])}</label><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="game-search" type="search" placeholder="{E(i['search'])}" autocomplete="off"></div></div><div class="game-filters" hidden role="group" aria-label="{E(t['collection'])}">{filters}</div><p class="collection-count"><span id="game-count" role="status" aria-live="polite">58 / 58</span> <span>{E(t['results'])}</span></p><p class="game-empty" id="game-empty" hidden>{E(i['empty'])}</p><div class="games-grid">{''.join(card(lang,g,i,route,types) for g in games)}</div></section>{cta(lang,i)}{support(lang,i)}'''
def page(lang,g,i,games,route,media,types,tips,prompt):
    d=g['locales'][lang];t=TEXT[lang];name=d['name'];category=types[ORDER.index(g['type'])]
    tipcards=''.join(f'<li><span>0{n+1}</span><p>{E(tip)}</p></li>' for n,tip in enumerate(tips))
    other=[x for x in games if x['type']==g['type'] and x['id']!=g['id']][:4]
    while len(other)<4:
        other.append(next(x for x in games if x['id']!=g['id'] and x not in other))
    return f'''<nav class="game-breadcrumb" aria-label="{E(i['all'])}"><a href="{i['base']}">← {E(i['all'])}</a><span>/</span><span>{E(name)}</span></nav><section class="game-hero tone-{g['type']}"><div class="game-hero-copy"><div class="game-identity"><img src="{icon(g['id'])}" alt="" width="80" height="80"><div><p class="game-kicker">{E(i['brand'])}</p><span class="game-category">{E(category)}</span></div></div><h1>{E(name)}</h1><p class="game-lead">{E(d['hook'])}</p><div class="game-rule"><span class="rule-symbol" aria-hidden="true">↗</span><div><h2>{E(t['how'])}</h2><p>{E(d['tutorial'])}</p></div></div>{store(lang,i)}<p class="hero-footnote">{E(t['android'])}<br>{E(t['languages'])}</p></div><div class="game-video-stage"><div class="video-stage-heading"><span>{E(t['demo'])}</span><span class="video-sound"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 9h4l5-4v14l-5-4H3zM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>{E(t['sound'])}</span></div><figure class="game-demo"><video controls playsinline preload="none" poster="{media(lang,g,'jpg')}" width="1080" height="1920" aria-label="{E(i['watch']+': '+name)}" aria-describedby="demo-summary"><source src="{media(lang,g,'mp4')}" type="video/mp4"><a href="{media(lang,g,'mp4')}">{E(i['watch'])}</a></video><figcaption id="demo-summary">{E(i['sound'])}</figcaption></figure></div></section><section class="game-together"><div class="section-title"><p class="game-kicker">{E(t['family'])}</p><h2>{E(i['together'])}</h2></div><div class="together-layout"><article class="game-specific-idea"><span class="idea-mark" aria-hidden="true">✳</span><p class="game-kicker">{E(t['next'])}</p><h3>{E(t['idea'])}</h3><p>{E(prompt)}</p></article><ol class="game-tips">{tipcards}</ol></div></section><section class="games-section"><div class="section-title"><p class="game-kicker">{E(t['discover'])}</p><h2>{E(i['more'])}</h2></div><div class="games-grid">{''.join(card(lang,x,i,route,types) for x in other)}</div><a class="game-back-link" href="{i['base']}">{E(t['explore'])}{arrow()}</a></section>{support(lang,i,compact=True)}{cta(lang,i)}'''
